import React, { useState } from 'react';
import './About.css';

const About = () => {
    const [activeTab, setActiveTab] = useState('org');

    const renderContent = () => {
        switch (activeTab) {
            case 'org':
                return (
                    <section className="about-section fade-in">
                        <div className="org-portfolio">
                            <h2>Organization Portfolio</h2>
                            <p className="subtitle">Your trusted partner in financial empowerment</p>
                            <div className="portfolio-grid">
                                <div className="portfolio-card"><h3>5.71 Arba</h3><p>Total Loan</p></div>
                                <div className="portfolio-card"><h3>1.33 Arba</h3><p>Total Savings</p></div>
                                <div className="portfolio-card"><h3>9,604</h3><p>Total Centers</p></div>
                                <div className="portfolio-card"><h3>1,05,820</h3><p>Total Members</p></div>
                            </div>
                        </div>
                    </section>
                );
            case 'ovm':
                return (
                    <section className="about-section fade-in">
                        <h2>Objective, Vision & Mission</h2>
                        <div className="ovmg-grid">
                            <div className="ovmg-card">
                                <h3>Vision</h3>
                                <p>To build a sustainable and inclusive society by promoting economic independence among Nepal’s marginalized populations.</p>
                            </div>
                            <div className="ovmg-card">
                                <h3>Mission</h3>
                                <p>To provide sustainable microfinance services to needy and underserved families across Nepal.</p>
                            </div>
                        </div>
                    </section>
                );
            case 'board':
                return (
                    <section className="about-section fade-in">
                        <h2>Board of Directors</h2>
                        <div className="board-grid">
                            <div className="board-card">
                                <img src="/assets/Bishnu_Sir.jpg" alt="Chairman" />
                                <h3>Mr. Bishnu Kumar Ghimire</h3>
                                <h4>Chairman</h4>
                                <p>M.A, M.Ed., B.L from Tribhuvan University. Founder principal and social worker.</p>
                            </div>
                            {/* Add more board cards here matching your HTML structure */}
                        </div>
                    </section>
                );
            case 'ceo':
                return (
                    <section className="ceo-message fade-in">
                        <div className="ceo-container">
                            <img src="/assets/ceo-sir.jpg" alt="CEO" className="ceo-img" />
                            <div className="ceo-text">
                                <h3>Gyanishor Panta</h3>
                                <h4>Chief Executive Officer</h4>
                                <p>"Our mission is clear: to bridge the gap in financial inclusion for Nepal’s rural and marginalized communities."</p>
                            </div>
                        </div>
                    </section>
                );
            default:
                return null;
        }
    };

    return (
        <div className="about-page">
            <div className="about-header">
                <h1>About Us</h1>
                <p>Infinity Laghubitta Bittiya Sanstha Limited</p>
            </div>

            <div className="tabs-container">
                <div className="tabs">
                    <button className={activeTab === 'org' ? 'active' : ''} onClick={() => setActiveTab('org')}>Our Organization</button>
                    <button className={activeTab === 'ovm' ? 'active' : ''} onClick={() => setActiveTab('ovm')}>Vision & Mission</button>
                    <button className={activeTab === 'board' ? 'active' : ''} onClick={() => setActiveTab('board')}>Board of Directors</button>
                    <button className={activeTab === 'ceo' ? 'active' : ''} onClick={() => setActiveTab('ceo')}>Message from CEO</button>
                </div>
            </div>

            <div className="container">
                {renderContent()}
            </div>
        </div>
    );
};

export default About;
